-- =====================================================================
-- BANKSHIELD AI — SUJET 6 (SMART AUTOMATION CHALLENGE 2026)
-- SCRIPT MASTER COMPLET : SCHÉMA DDL, INDEXES, FONCTIONS & DATASET PEUPLÉ
-- BASE DE DONNÉES : SUPABASE CLOUD (POSTGRESQL 15)
-- AUTEURS : Jihane Majdoul, Salma Boukhlal, Abdelouahed Ahnid, Yassine Hadrane, Youssef Ait Bakrim
-- DATE D'EXPORTATION OFFICIELLE : JEUDI 17 SEPTEMBRE 2026
-- =====================================================================

-- ---------------------------------------------------------------------
-- 0. EXTENSIONS POSTGRESQL NÉCESSAIRES
-- ---------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ---------------------------------------------------------------------
-- 1. NETTOYAGE PRÉVENTIF EN CASCADE (RÉ-EXÉCUTABLE SANS CONFLIT)
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS public.fraud_alerts CASCADE;
DROP TABLE IF EXISTS public.risk_evaluations CASCADE;
DROP TABLE IF EXISTS public.transactions CASCADE;
DROP TABLE IF EXISTS public.customers CASCADE;

-- ---------------------------------------------------------------------
-- 2. TABLE : customers (RÉFÉRENTIEL DES 10 CLIENTS AVEC BASELINE ET LIMITES)
-- ---------------------------------------------------------------------
CREATE TABLE public.customers (
  customer_id VARCHAR(20) PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL,
  cin VARCHAR(20) UNIQUE NOT NULL,
  primary_rib CHAR(24) UNIQUE NOT NULL,
  phone_number VARCHAR(20) NOT NULL,
  home_city VARCHAR(50) NOT NULL,
  avg_transaction_amount NUMERIC(10,2) NOT NULL DEFAULT 350.00,
  avg_daily_transactions NUMERIC(4,1) NOT NULL DEFAULT 2.5,
  avg_weekly_transactions NUMERIC(5,1) NOT NULL DEFAULT 15.0,
  daily_limit NUMERIC(10,2) NOT NULL DEFAULT 10000.00,
  current_balance NUMERIC(12,2) NOT NULL DEFAULT 25000.00,
  trusted_beneficiaries JSONB DEFAULT '[]'::jsonb,
  trusted_devices JSONB DEFAULT '[]'::jsonb,
  last_location_city VARCHAR(50) DEFAULT 'Casablanca',
  last_transaction_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- 3. TABLE : transactions (FLUX FINANCIERS TRANSACTIONNELS TEMPS RÉEL)
-- ---------------------------------------------------------------------
CREATE TABLE public.transactions (
  id BIGSERIAL PRIMARY KEY,
  transaction_id VARCHAR(50) UNIQUE NOT NULL DEFAULT ('TRX-' || TO_CHAR(NOW(), 'YYMMDD-') || UPPER(SUBSTRING(gen_random_uuid()::TEXT, 1, 8))),
  customer_id VARCHAR(20) NOT NULL REFERENCES public.customers(customer_id) ON DELETE CASCADE,
  source_rib CHAR(24) NOT NULL,
  card_pan_masked VARCHAR(20) DEFAULT '4532 **** **** 1024',
  transaction_type VARCHAR(30) NOT NULL DEFAULT 'CARD_PAYMENT' CHECK (transaction_type IN ('CARD_PAYMENT', 'TRANSFER', 'ATM_WITHDRAWAL', 'ONLINE_PAYMENT')),
  amount NUMERIC(12,2) NOT NULL,
  currency VARCHAR(5) NOT NULL DEFAULT 'MAD',
  channel VARCHAR(30) NOT NULL DEFAULT 'pos_terminal' CHECK (channel IN ('pos_terminal', 'web_banking', 'mobile_app', 'atm_gab', 'branch')),
  beneficiary_name VARCHAR(100),
  beneficiary_rib CHAR(24),
  merchant_category VARCHAR(50) DEFAULT 'general',
  location_city VARCHAR(50) NOT NULL DEFAULT 'Casablanca',
  location_country VARCHAR(5) NOT NULL DEFAULT 'MA',
  ip_address VARCHAR(45) DEFAULT '196.200.145.22',
  device_id VARCHAR(100),
  auth_factor VARCHAR(30) DEFAULT 'BIOMETRIC' CHECK (auth_factor IN ('CHIP_AND_PIN', 'BIOMETRIC', 'SMS_OTP', 'NONE')),
  prev_location_city VARCHAR(50) DEFAULT 'Casablanca',
  prev_transaction_at TIMESTAMPTZ,
  timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  tx_count_last_10m INTEGER NOT NULL DEFAULT 1,
  tx_count_last_hour INTEGER NOT NULL DEFAULT 1,
  tx_count_today INTEGER NOT NULL DEFAULT 1,
  daily_cumulative_amount NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  customer_avg_daily_tx_count NUMERIC(4,2) DEFAULT 2.0,
  is_cheked BOOLEAN NOT NULL DEFAULT FALSE
);

-- ---------------------------------------------------------------------
-- 4. TABLE : risk_evaluations (ÉVALUATION DES RISQUES & RÈGLES EXPERTES)
-- ---------------------------------------------------------------------
CREATE TABLE public.risk_evaluations (
  evaluation_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  transaction_id VARCHAR(50) NOT NULL REFERENCES public.transactions(transaction_id) ON DELETE CASCADE,
  customer_id VARCHAR(20) NOT NULL REFERENCES public.customers(customer_id) ON DELETE CASCADE,
  risk_score NUMERIC(5,2) NOT NULL CHECK (risk_score >= 0 AND risk_score <= 100),
  risk_level VARCHAR(20) NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  engine_decision VARCHAR(20) NOT NULL CHECK (engine_decision IN ('APPROVED', 'CHALLENGED', 'BLOCKED')),
  triggered_rules JSONB DEFAULT '[]'::jsonb,
  applied_mitigations JSONB DEFAULT '[]'::jsonb,
  processing_time_ms INTEGER DEFAULT 120,
  evaluated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- 5. TABLE : fraud_alerts (ALERTES FRAUDE & ENQUÊTES SOC POUR ANALYSTE)
-- ---------------------------------------------------------------------
CREATE TABLE public.fraud_alerts (
  alert_id BIGSERIAL PRIMARY KEY,
  transaction_id VARCHAR(50) NOT NULL REFERENCES public.transactions(transaction_id) ON DELETE CASCADE,
  customer_id VARCHAR(20) NOT NULL REFERENCES public.customers(customer_id) ON DELETE CASCADE,
  severity VARCHAR(20) NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  ai_investigation_summary TEXT,
  ai_recommendation VARCHAR(255),
  slack_thread_ts VARCHAR(50),
  analyst_decision VARCHAR(30) DEFAULT 'PENDING' CHECK (analyst_decision IN ('PENDING', 'CONFIRMED_FRAUD', 'FALSE_POSITIVE')),
  analyst_notes TEXT,
  decided_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- 6. CONFIGURATION REPLICA IDENTITY FULL POUR RÉPLICATION EN TEMPS RÉEL
-- ---------------------------------------------------------------------
ALTER TABLE public.transactions REPLICA IDENTITY FULL;
ALTER TABLE public.risk_evaluations REPLICA IDENTITY FULL;
ALTER TABLE public.fraud_alerts REPLICA IDENTITY FULL;

-- ---------------------------------------------------------------------
-- 7. INDEX DE HAUTE PERFORMANCE (LATENCE < 5MS)
-- ---------------------------------------------------------------------
CREATE INDEX idx_customers_phone ON public.customers(phone_number);
CREATE INDEX idx_customers_rib ON public.customers(primary_rib);
CREATE INDEX idx_transactions_customer ON public.transactions(customer_id);
CREATE INDEX idx_transactions_timestamp ON public.transactions(timestamp DESC);
CREATE INDEX idx_transactions_txn_id ON public.transactions(transaction_id);
CREATE INDEX idx_transactions_is_cheked ON public.transactions(is_cheked);
CREATE INDEX idx_risk_eval_txn ON public.risk_evaluations(transaction_id);
CREATE INDEX idx_risk_eval_score ON public.risk_evaluations(risk_score DESC);
CREATE INDEX idx_risk_eval_decision ON public.risk_evaluations(engine_decision);
CREATE INDEX idx_fraud_alerts_txn ON public.fraud_alerts(transaction_id);
CREATE INDEX idx_fraud_alerts_severity ON public.fraud_alerts(severity);
CREATE INDEX idx_fraud_alerts_decision ON public.fraud_alerts(analyst_decision);

-- ---------------------------------------------------------------------
-- 8. FONCTION PL/PGSQL : CALCUL DYNAMIQUE DES MÉTRIQUES DE VÉLOCITÉ
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_get_customer_frequency_metrics(p_customer_id VARCHAR)
RETURNS TABLE (
    customer_id VARCHAR,
    tx_count_last_10m BIGINT,
    tx_count_last_hour BIGINT,
    tx_count_today BIGINT,
    daily_cumulative_amount NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        p_customer_id,
        COALESCE(COUNT(CASE WHEN t.timestamp >= NOW() - INTERVAL '10 minutes' THEN 1 END), 0)::BIGINT AS tx_count_last_10m,
        COALESCE(COUNT(CASE WHEN t.timestamp >= NOW() - INTERVAL '1 hour' THEN 1 END), 0)::BIGINT AS tx_count_last_hour,
        COALESCE(COUNT(CASE WHEN t.timestamp >= DATE_TRUNC('day', NOW()) THEN 1 END), 0)::BIGINT AS tx_count_today,
        COALESCE(SUM(CASE WHEN t.timestamp >= DATE_TRUNC('day', NOW()) THEN t.amount ELSE 0 END), 0.00)::NUMERIC AS daily_cumulative_amount
    FROM public.transactions t
    WHERE t.customer_id = p_customer_id;
END;
$$ LANGUAGE plpgsql;

