  (74, 'TRX-APP-1789548921-146', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD effectuée via terminal de paiement (POS). La règle RG-12 a été déclenchée. Les métriques de vélocité indiquent une activité normale avec une seule transaction enregistrée aujourd''hui.', 'Vérifier la cohérence de la localisation du terminal de paiement avec les habitudes du client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T08:55:29.736167+00:00'),
  (75, 'TRX-APP-1789549701-938', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD effectuée via terminal de paiement (POS). La règle RG-12 a été déclenchée. Les métriques de vélocité montrent une activité normale avec une seule transaction enregistrée aujourd''hui.', 'Vérifier la cohérence de la localisation du terminal de paiement avec les habitudes du client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:08:29.648311+00:00'),
  (76, 'TRX-APP-1789549674-428', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. La règle RG-12 a été déclenchée. Le niveau de risque est bas.', 'Vérifier la conformité du paiement physique.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:24.743313+00:00'),
  (77, 'TRX-APP-1789550045-705', 'CUST-1001', 'CRITICAL', 'Transaction web de 22 000 MAD. Risque élevé dû à un montant extrême, un nouveau bénéficiaire, un pays inhabituel et une alerte de changement de canal (SIM-swap).', 'Contacter le client pour authentification forte et vérifier le changement de canal.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:25.640695+00:00'),
  (78, 'TRX-APP-1789550203-565', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. Déclenchement des règles RG-03 (dépassement plafond) et RG-08 (vélocité).', 'Vérifier le plafond autorisé du client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:26.386512+00:00'),
  (79, 'TRX-APP-1789549561-640', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE validée par la règle RG-12. Risque faible identifié.', 'Aucune action spécifique requise.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:27.140233+00:00'),
  (80, 'TRX-APP-1789549537-313', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. La règle RG-12 confirme le paiement physique.', 'Aucune action spécifique requise.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:27.898327+00:00'),
  (81, 'TRX-APP-1789549583-271', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. La règle RG-12 a été déclenchée.', 'Aucune action spécifique requise.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:28.643647+00:00'),
  (82, 'TRX-APP-1789549690-784', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. Déclenchement de la règle RG-08 concernant la vélocité des transactions.', 'Vérifier la fréquence des transactions récentes.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:29.397261+00:00'),
  (83, 'TRX-APP-1789550128-164', 'CUST-1001', 'CRITICAL', 'Transaction web de 22 000 MAD. Facteurs de risque : montant extrême, nouveau bénéficiaire, pays inhabituel et suspicion de SIM-swap.', 'Bloquer temporairement et contacter le client pour vérification.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:30.155132+00:00'),
  (84, 'TRX-APP-1789550145-381', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via TPE. Déclenchement des règles RG-03 (plafond) et RG-08 (vélocité).', 'Vérifier les paramètres de plafond du compte.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:30.912489+00:00'),
  (85, 'TRX-APP-1789550256-166', 'CUST-1001', 'MEDIUM', 'Transaction de 350 MAD via terminal de paiement (POS). Le risque est lié au dépassement de plafond, à une alerte de vélocité de type rafale et à la nature physique de l''opération.', 'Vérifier la cohérence de cette transaction avec les habitudes de dépenses habituelles du client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:17:51.093808+00:00'),
  (86, 'TRX-APP-1789550494-977', 'CUST-1005', 'MEDIUM', 'Transaction de 550 MAD via terminal de paiement (POS). Le moteur a déclenché la règle RG-00 indiquant que le profil client est introuvable, malgré une validation par la règle RG-12. La vélocité est normale avec une seule transaction enregistrée.', 'Vérifier l''identité du porteur de la carte et la cohérence des informations du profil client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:21:44.70144+00:00'),
  (87, 'TRX-APP-1789550494-977', 'CUST-1005', 'MEDIUM', 'Transaction de 550 MAD effectuée via terminal de paiement (POS). La règle RG-12 a été déclenchée. Les métriques de vélocité indiquent une activité normale avec une seule transaction enregistrée aujourd''hui.', 'Vérifier la conformité de la transaction avec les habitudes de dépenses habituelles du client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:21:44.967935+00:00'),
  (88, 'TRX-APP-1789550653-841', 'CUST-1005', 'CRITICAL', 'Transaction de 18 500 MAD via web_banking. Le risque est élevé en raison d''un montant extrême, d''un vidage de solde, de l''ajout d''un nouveau bénéficiaire et d''une alerte sur le canal (SIM-swap). Le profil client est également introuvable.', 'Vérifier l''identité du client et confirmer la légitimité de l''ajout du nouveau bénéficiaire.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:24:21.569411+00:00'),
  (89, 'TRX-APP-1789550653-841', 'CUST-1005', 'CRITICAL', 'Transaction de 18 500 MAD via web_banking. Le risque est élevé en raison du montant extrême, du dépassement de plafond, de l''ajout d''un nouveau bénéficiaire et d''une alerte liée à un changement de canal (SIM-swap).', 'Contacter le client par téléphone pour confirmer l''ajout du bénéficiaire et l''exécution de cette transaction.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:24:21.969152+00:00'),
  (90, 'TRX-APP-1789550942-433', 'CUST-1005', 'CRITICAL', 'Transaction de 18 500 MAD via web_banking. Le risque est élevé en raison du montant extrême, du vidage de solde, du dépassement de plafond et de l''ajout d''un nouveau bénéficiaire. Le profil client est introuvable et une alerte de changement de canal (SIM-swap) a été déclenchée.', 'Contacter le client par téléphone pour vérifier l''authenticité de la transaction et l''ajout du nouveau bénéficiaire.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:29:11.148694+00:00'),
  (91, 'TRX-APP-1789550942-433', 'CUST-1005', 'CRITICAL', 'Transaction de 18 500 MAD via web_banking. Le risque est élevé en raison du montant extrême, du dépassement de plafond, de l''ajout d''un nouveau bénéficiaire et d''une alerte potentielle de changement de canal (SIM-swap).', 'Vérifier l''identité du client et confirmer la légitimité de l''ajout du nouveau bénéficiaire.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:29:11.908518+00:00'),
  (92, 'TRX-APP-1789550942-433', 'CUST-1005', 'CRITICAL', 'Transaction web_banking de 18 500 MAD. Le risque est élevé en raison d''un montant extrême, d''un vidage de solde, d''un dépassement de plafond et de l''ajout d''un nouveau bénéficiaire. Le profil client est introuvable et une alerte de changement de canal (SIM-swap) a été déclenchée.', 'Contacter le client par téléphone pour confirmer l''opération et vérifier l''identité du nouveau bénéficiaire.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:31:07.467877+00:00'),
  (93, 'TRX-APP-1789551436-861', 'CUST-1004', 'CRITICAL', 'Transaction de 22 000 MAD via web_banking. Le risque est élevé en raison de règles déclenchées concernant un montant extrême, un vidage de solde, un dépassement de plafond, une localisation inhabituelle, un nouveau bénéficiaire et une suspicion de changement de canal (SIM-swap).', 'Contacter le client par téléphone pour vérifier l''authenticité de cette opération et confirmer le changement de canal.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:37:38.537226+00:00'),
  (94, 'TRX-APP-1789551418-686', 'CUST-1005', 'CRITICAL', 'Transaction de 22 000 MAD via web_banking. Le risque est élevé en raison de multiples alertes critiques : montant extrême, vidage de solde, dépassement de plafond, nouveau bénéficiaire et détection d''un changement de canal suspect (SIM-swap). Le profil client est également introuvable.', 'Contacter le client par téléphone pour vérifier l''authenticité de cette opération et confirmer le changement de canal.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:40:03.373552+00:00'),
  (95, 'TRX-APP-1789551418-686', 'CUST-1005', 'CRITICAL', 'Transaction de 22 000 MAD via web_banking. Le risque est élevé en raison du montant extrême, du dépassement de plafond, d''une localisation inhabituelle, de l''ajout d''un nouveau bénéficiaire et d''une alerte sur un changement de canal (SIM-swap).', 'Contacter le client par téléphone pour vérifier la légitimité de la transaction et confirmer le changement de canal.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:40:03.712442+00:00'),
  (96, 'TRX-APP-1789551418-686', 'CUST-1005', 'CRITICAL', 'Transaction de 22 000 MAD via web_banking. Le risque est élevé en raison du montant extrême, du dépassement de plafond, d''une localisation inhabituelle, d''un nouveau bénéficiaire et d''une alerte liée à un changement de canal (SIM-swap).', 'Contacter le client par téléphone pour confirmer l''opération et vérifier l''intégrité de sa carte SIM.', NULL, 'PENDING', NULL, NULL, '2026-09-16T09:40:04.012585+00:00'),
  (101, 'TRX-DEMO-2026-001', 'CUST-1001', 'CRITICAL', 'Voyage physiquement impossible détecté par formule de Haversine (distance 2380 km parcourue en 15 min). Dépassement du plafond journalier (22 000 MAD vs 10 000 MAD). Destination étrangère à haut risque (Sénégal) via navigateur anonyme Tor.', 'Blocage immédiat du virement, révocation temporaire de session web-banking et notification SMS d''urgence.', '178950001.000100', 'CONFIRMED_FRAUD', 'Fraude confirmée par l''analyste SOC suite à tentative d''accès frauduleux depuis Dakar.', '2026-09-16T09:47:01.540931+00:00', '2026-09-16T09:44:01.540931+00:00'),
  (102, 'TRX-DEMO-2026-002', 'CUST-1002', 'CRITICAL', 'Attaque en rafale / botnet : 5 transactions successives en 10 minutes à 04h10 du matin depuis un émulateur Android inconnu. Cumul journalier dépassant le plafond autorisé.', 'Blocage de l''appareil émulateur, suspension conservatoire de la carte et vérification bancaire.', '178950002.000100', 'PENDING', 'Sous investigation SOC L2 : suspicion de credentials stuffing ou malware bancaire.', NULL, '2026-09-16T09:41:01.540931+00:00'),
  (103, 'TRX-DEMO-2026-003', 'CUST-1003', 'CRITICAL', 'Tentative de siphonnage de compte vers plateforme crypto P2P non régulée à 02h45 du matin via IP proxy connue. Montant de 28 000 MAD excédant le plafond journalier.', 'Rejet immédiat du virement, blocage préventif des virements sortants et contact client.', '178950003.000100', 'PENDING', 'Alerte prioritaire générée automatiquement. Notification Slack transmise au niveau L2.', NULL, '2026-09-16T09:38:01.540931+00:00'),
  (104, 'TRX-DEMO-2026-004', 'CUST-1004', 'MEDIUM', 'Montant élevé (7 990 MAD) mais opération physique réalisée en magasin de confiance avec saisie du code PIN secret dans la ville de résidence habituelle. Atténuation maximale appliquée.', 'Approbation automatique sans friction. Risque résiduel nul.', '178950004.000100', 'FALSE_POSITIVE', 'Faux positif avéré : achat légitime d''électroménager avec authentification forte.', '2026-09-16T09:47:01.540931+00:00', '2026-09-16T09:35:01.540931+00:00'),
  (105, 'TRX-DEMO-2026-005', 'CUST-1005', 'MEDIUM', 'Déplacement Fès -> Agadir (650 km) en 2 heures détecté. Présence physique de la carte sur TPE hôtelier, atténuant partiellement le risque de clonage.', 'Demande de confirmation 3D Secure / notification Push in-app au titulaire.', '178950005.000100', 'CONFIRMED_FRAUD', 'Client potentiellement en déplacement professionnel par vol intérieur.', '2026-09-16T10:19:42.429+00:00', '2026-09-16T09:32:01.540931+00:00'),
  (106, 'TRX-DEMO-2026-006', 'CUST-1006', 'MEDIUM', 'Paiement en ligne sur site e-commerce international américain à heure tardive. Carte enregistrée sur terminal habituel mais marchand inconnu du profil.', 'Validation soumise à confirmation OTP SMS.', '178950006.000100', 'PENDING', 'Challenge 2FA délivré avec succès au numéro de téléphone du client.', NULL, '2026-09-16T09:29:01.540931+00:00'),
  (107, 'TRX-DEMO-2026-007', 'CUST-1007', 'CRITICAL', 'Suspicion de détournement de compte par SIM-Swap : virement international de 18 500 MAD dépassant de 200% le plafond journalier de 9 000 MAD, opéré immédiatement après connexion depuis un nouvel équipement.', 'Blocage immédiat du canal Web Banking, invalidation des sessions actives et mise sous quarantaine.', '178950007.000100', 'CONFIRMED_FRAUD', 'Contact téléphonique d''urgence établi : le client confirme n''avoir initié aucun virement.', '2026-09-16T09:47:01.540931+00:00', '2026-09-16T09:26:01.540931+00:00'),
  (108, 'TRX-APP-1789553254-125', 'CUST-1003', 'MEDIUM', 'Transaction de 850 MAD effectuée via terminal de paiement (POS). Le moteur a déclenché la règle RG-00 indiquant que le profil client est introuvable, malgré une activité conforme aux métriques de vélocité habituelles.', 'Vérifier l''identité du porteur de la carte et la cohérence des informations du profil client.', NULL, 'PENDING', NULL, NULL, '2026-09-16T10:07:40.932046+00:00'),
