SELECT setval(pg_get_serial_sequence('public.fraud_alerts', 'alert_id'), COALESCE((SELECT MAX(alert_id) FROM public.fraud_alerts), 1));

-- ---------------------------------------------------------------------
-- 13. REQUÊTES DE CONTRÔLE D'INTÉGRITÉ & DE STATISTIQUES
-- ---------------------------------------------------------------------
SELECT 'customers' AS table_name, count(*) AS total_records FROM public.customers
UNION ALL
SELECT 'transactions', count(*) FROM public.transactions
UNION ALL
SELECT 'risk_evaluations', count(*) FROM public.risk_evaluations
UNION ALL
SELECT 'fraud_alerts', count(*) FROM public.fraud_alerts;

-- Synthèse de la répartition des décisions du moteur :
SELECT engine_decision, COUNT(*) AS count, ROUND(AVG(risk_score), 2) AS avg_score
FROM public.risk_evaluations
GROUP BY engine_decision;

-- Synthèse des alertes par sévérité :
SELECT severity, analyst_decision, COUNT(*) AS count
FROM public.fraud_alerts
GROUP BY severity, analyst_decision;
